def get_axioms() -> list:
    return []


def get_vars() -> dict:
    elements = TensorVar('elements')
    test_elements = TensorVar('test_elements')
    out = TensorVar('out')
    tensor_5 = TensorVar('tensor_5')
    return {'elements': elements, 'test_elements': test_elements, 'out': out, 'tensor_5': tensor_5}


def build_solver() -> Solver:
    s = Solver()
    s.add(*get_axioms())
    return s


def get_constraints() -> list:
    # OUTPUT-SHAPE FIX: isin(elements, test_elements) -> out.shape == elements shape.
    # resize_output hard-errors on wrong non-empty out; require empty or exact.
    elements = TensorVar('elements')
    out = TensorVar('out')
    out_ok = Or(out.numel() == 0, same_shape(out, elements))
    return [Or(c, Not(out_ok)) for c in _get_constraints_orig()]
